                            C8 (wz (rg_allocated_user r)); C8 (wz 0); C8 (wz (rg_mapped_user r)); C8 (wz 0)]
    /\ stk bsegs m (RI + 64) (RI + 68) /\ rw_cells bsegs m (RI + 68) [C1 (b8 0)] /\ stk bsegs m (RI + 69) (RI + 128)
    /\ u32arr bsegs m (FA s c) (wlist (rev (rg_free_array r)))
    /\ stk bsegs m (FA s c + 4 * rg_num_freed r) (FA s c + rg_mapped_free_array r)
    /\ stk bsegs m (RB s c + rg_allocated_user r) (RB s c + rg_mapped_user r)
